    // Publications: publications, text with quotes.
    'publications.noPeerIsConnectedSo2': 'Nenhum par está conectado, então “Recuperar dos pares” não consegue buscar o conteúdo que falta. Conecte-se a um em {peers}.',
    'publications.thisIsACorrelationOf2': 'Esta é uma correlação de fatos registrados de forma independente, por anchorId explícito — não um veredito. Veja “Evidências históricas de âncoras no Bitcoin” acima para o detalhamento completo, por observação, deste mesmo anchorId.',
    'publications.thisIsAReadOnly': 'Esta é uma visualização somente leitura do arquivo acima — ela não muda nada no Arquivo de observações mostrado antes nesta página. Use “Importar arquivo” acima se quiser que este arquivo o substitua.',
    'publications.whatReplacingTheCurrentArchive': 'O que mudaria ao substituir o arquivo atual pelo arquivo externo acima — o arquivo atual fica exatamente como está até que você clique explicitamente em “Substituir o arquivo atual” abaixo.',
    'publications.replacingRestampsEveryFactIn': 'A substituição remarca cada fato do arquivo externo acima como IMPORTED (0.8.83) — por isso a impressão digital atual resultante será diferente da “Impressão digital externa” mostrada acima, mesmo que as observações subjacentes sejam idênticas.',
    'publications.localFactsWereObservedBy': 'Os fatos locais foram observados diretamente por esta réplica. Os fatos importados entraram neste arquivo por uma importação anterior com “Substituir o arquivo atual”. Nenhum é mais confiável que o outro — isto só informa de onde cada fato veio.',
    'publications.anExplicitDurableRecordThat2': 'Um registro explícito e durável de que uma publicação faz referência a outra — nunca deduzido de conteúdo, horários ou autores coincidentes. As duas publicações já precisam ter uma identidade durável acima; uma referência nunca é uma classificação como “bifurcação”, apenas um fato simples e atribuível: esta publicação aponta para aquela.',
    'publications.nothingHereIsSavedAnywhere': 'Nada aqui é salvo em lugar nenhum. Esta configuração existe só na memória desta página durante esta sessão de navegação e é descartada assim que a página é recarregada ou que você clica em “Limpar configuração”.',
    'publications.thisReplicaDoesNotCurrently': 'Esta réplica não tem um snapshot válido no momento. Escolha uma origem abaixo — “Importar Snapshot”, o “Materializar Snapshot” de um posicionamento ou o “Obter Snapshot do par” de um par — para tentar de novo.',

    // Publications: leaderboardHubView, text with quotes.
    'leaderboardHubView.aBadgePresentationOfThe': 'Uma apresentação em emblemas das conquistas que este editor já obteve, em todas as publicações que ele reivindicou explicitamente — nunca uma conquista nova e nunca uma pontuação, posição ou entrada na classificação. Algumas conquistas (as derivadas de referências) ainda não têm apresentação em emblema e aparecem só no cartão “Perfil de conquistas do editor” acima.',

    // Publications: publisherLeaderboardSnapshotClaimAuthoringView, text with quotes.
    'publisherLeaderboardSnapshotClaimAuthoringView.authorAndExportASigned': 'Crie e exporte uma declaração assinada sobre o snapshot atual da classificação da SUA PRÓPRIA réplica — exatamente o artefato de evidência que o campo “Evidência do par” do Espaço de conciliação pede que um par cole. Gerar, assinar e exportar são três ações separadas e explícitas; nada nesta página é executado automaticamente.',
    'publisherLeaderboardSnapshotClaimAuthoringView.pasteThisIntoAPeer': 'Cole isto no campo “Evidência do par” do Espaço de conciliação de um par, ou envie a ele o arquivo baixado.',

    // Publications: reconciliationCandidateLeaderboardView, text with quotes.
    'reconciliationCandidateLeaderboardView.noPeerArchiveSuppliedYet': 'Nenhum arquivo de par fornecido ainda — todas as contagens abaixo são só da origem até você colar um. Cole o arquivo exportado pela réplica de um par (Exportar arquivo, na página Publicações) e clique em “Usar como arquivo do par”.',

    // Publications: reconciliationWorkspaceView, text with quotes.
    'reconciliationWorkspaceView.reconcileThisReplicaSOwn': 'Concilie o arquivo local desta réplica com uma evidência de par, explicitamente. Nada nesta página é executado automaticamente — a conciliação só acontece quando você clica em “Conciliar”, abaixo.',

