    'blurtSettingsView.whereThisReplicaReadsBlurt': 'De onde esta réplica lê as postagens do Blurt: publicações (Mundos Compartilhados, Atribuições de Plantas e nomes de lugares), Snapshots e comentários, que as pessoas publicam de suas próprias contas como postagens principais com a tag forkbuild. Elas são lidas pelo Nexus, o indexador do Blurt, que lista todas as postagens com a tag, não importa a idade; um nó sem Nexus é ignorado. Se nenhum nó o tiver, a tag lista uma postagem só até ela ser paga, após sete dias, e as postagens mais antigas são lidas do histórico das contas que este dispositivo viu publicar. Cada anúncio é verificado antes de ser usado. Ler não exige uma conta do Blurt. As alterações valem na próxima vez que o app for carregado.',
